package com.termux.app.workspace;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.*;import com.termux.R;import com.termux.app.TermuxActivity;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.nio.file.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentProjectAttachmentsTest {
 void settle(AgentProjectPanel p)throws Exception{for(int n=0;n<300&&p.attachmentChecks>0;n++){Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertEquals(0,p.attachmentChecks);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 @Test public void originalsThumbnailsDownloadsAndColdPanelForAllAgents()throws Exception{
  for(String agent:new String[]{"codex","claude","gemini","opencode"})for(boolean managed:new boolean[]{true,false}){
   TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);WorkspaceLanguage.select(a,"en");WorkspaceStore.Session profile=new WorkspaceStore.Session();profile.environment=agent.equals("codex")?"codex":"ubuntu";profile.claudeAgent=agent.equals("claude");profile.geminiAgent=agent.equals("gemini");profile.aiAgent=agent.equals("opencode")?agent:"";
   File dir=new File(ChatAttachments.root(a,profile),"0123456789abcdef0123456789abcdef");dir.mkdirs();File original=new File(dir,"original.png");Bitmap bmp=Bitmap.createBitmap(60,40,Bitmap.Config.ARGB_8888);bmp.eraseColor(Color.BLUE);try(OutputStream os=new FileOutputStream(original)){assertTrue(bmp.compress(Bitmap.CompressFormat.PNG,100,os));}bmp.recycle();byte[] bytes=Files.readAllBytes(original.toPath());File downloads=new File(a.getCacheDir(),agent+managed+"-exports");
   String path=managed?ChatAttachments.prefix(profile)+dir.getName()+"/original.png":"/project/generated.png";String[] opened={""},jumped={""},location={""};JSONObject file=new JSONObject().put("path",path).put("name","a long photograph.png").put("type","image");JSONObject row=new JSONObject().put("key","row").put("message","m").put("messageSender",managed?"user":"agent").put("attachment",file);
   for(int cold=0;cold<2;cold++){
    AgentProjectPanel.Chat chat=new AgentProjectPanel.Chat(){public boolean valid(){return true;}public List<JSONObject> rows(){return Arrays.asList(row);}public boolean hasOlder(){return false;}public void older(){fail();}public void open(JSONObject f){opened[0]=f.optString("path");}public boolean jump(String key){jumped[0]=key;return true;}public void observe(Runnable r){}public void close(){}};
    AgentProjectPanel.Backend backend=new AgentProjectPanel.Backend(){public byte[] read(String s,int max){assertFalse("Managed originals must not use guest availability shell",managed);return ("AVAILABLE "+bytes.length).getBytes();}public File original(JSONObject f){return original;}public void close(){}};
    AgentProjectPanel panel=new AgentProjectPanel(a,profile,"/project",chat,backend);panel.downloadRoot=downloads;View root=panel.wrap(new LinearLayout(a),x->{},x->location[0]=x);
    try{panel.select(1);settle(panel);ImageView thumb=root.findViewWithTag("project-attachment-thumbnail-row");assertTrue(thumb.getDrawable() instanceof BitmapDrawable);assertNull(thumb.getColorFilter());assertEquals("File available",((TextView)root.findViewWithTag("project-file-availability")).getText().toString());thumb.performClick();assertEquals(path,opened[0]);LinearLayout strip=root.findViewWithTag("project-attachment-actions-row");assertEquals(3,strip.getChildCount());assertEquals("Go to message",((TextView)strip.getChildAt(0)).getText().toString());assertEquals("To Download",((TextView)strip.getChildAt(1)).getText().toString());strip.getChildAt(0).performClick();assertEquals("row",jumped[0]);TextView save=(TextView)strip.getChildAt(1);save.performClick();for(int n=0;n<300&&!save.isEnabled();n++){Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertTrue(save.isEnabled());File output=new File(downloads,cold==0?"a long photograph.png":"a long photograph-2.png");assertArrayEquals(bytes,Files.readAllBytes(output.toPath()));assertArrayEquals(bytes,Files.readAllBytes(new File(downloads,"a long photograph.png").toPath()));assertArrayEquals(bytes,Files.readAllBytes(original.toPath()));strip.getChildAt(2).performClick();assertEquals(new File(path).getParent(),location[0]);
     if(managed&&cold==1){assertTrue(original.delete());panel.select(1);settle(panel);assertEquals("File missing; record retained",((TextView)root.findViewWithTag("project-file-availability")).getText().toString());}
    }finally{panel.close();}
   }
   String mount=ProjectFiles.attachmentMount(profile,a.getFilesDir());assertTrue(mount.contains("--bind"));assertTrue(mount.contains("/chat-attachments:"));assertTrue(mount.contains(ChatAttachments.prefix(profile).replaceAll("/$","")));assertEquals("",ProjectFiles.attachmentMount(new WorkspaceStore.Session(),a.getFilesDir()));a.finish();
  }
 }
}
